-- Short random link codes (letter first, no look-alikes) for the business records whose
-- pages are linked: customers, suppliers, goods receipts, website requests, payroll runs.
-- Same scheme as invoices (20261118140000_invoice_ref). Each table: add the column, give
-- every row a code, re-roll any code that came out twice, then make it unique.

-- Customer
ALTER TABLE `Customer` ADD COLUMN `ref` VARCHAR(12) NULL;
UPDATE `Customer` SET `ref` = CONCAT(SUBSTRING('ABCDEFGHJKMNPQRSTUVWXYZ', 1 + FLOOR(RAND() * 23), 1), SUBSTRING('ABCDEFGHJKMNPQRSTUVWXYZ23456789', 1 + FLOOR(RAND() * 31), 1), SUBSTRING('ABCDEFGHJKMNPQRSTUVWXYZ23456789', 1 + FLOOR(RAND() * 31), 1), SUBSTRING('ABCDEFGHJKMNPQRSTUVWXYZ23456789', 1 + FLOOR(RAND() * 31), 1), SUBSTRING('ABCDEFGHJKMNPQRSTUVWXYZ23456789', 1 + FLOOR(RAND() * 31), 1), SUBSTRING('ABCDEFGHJKMNPQRSTUVWXYZ23456789', 1 + FLOOR(RAND() * 31), 1)) WHERE `ref` IS NULL;
UPDATE `Customer` SET `ref` = CONCAT(SUBSTRING('ABCDEFGHJKMNPQRSTUVWXYZ', 1 + FLOOR(RAND() * 23), 1), SUBSTRING('ABCDEFGHJKMNPQRSTUVWXYZ23456789', 1 + FLOOR(RAND() * 31), 1), SUBSTRING('ABCDEFGHJKMNPQRSTUVWXYZ23456789', 1 + FLOOR(RAND() * 31), 1), SUBSTRING('ABCDEFGHJKMNPQRSTUVWXYZ23456789', 1 + FLOOR(RAND() * 31), 1), SUBSTRING('ABCDEFGHJKMNPQRSTUVWXYZ23456789', 1 + FLOOR(RAND() * 31), 1), SUBSTRING('ABCDEFGHJKMNPQRSTUVWXYZ23456789', 1 + FLOOR(RAND() * 31), 1))
WHERE `ref` IN (SELECT `ref` FROM (SELECT `ref` FROM `Customer` WHERE `ref` IS NOT NULL GROUP BY `ref` HAVING COUNT(*) > 1) AS dup);
