WHERE `ref` IN (SELECT `ref` FROM (SELECT `ref` FROM `Customer` WHERE `ref` IS NOT NULL GROUP BY `ref` HAVING COUNT(*) > 1) AS dup);
CREATE UNIQUE INDEX `Customer_ref_key` ON `Customer`(`ref`);
-- Touch every row so branch laptops (which pull changes since their last sync) receive the new codes.
UPDATE `Customer` SET `updatedAt` = NOW(3);

